set-variable.value:
@{
      var media = context.Request.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
      if (!String.Equals(media, "application/json", StringComparison.OrdinalIgnoreCase)) { return String.Empty; }
      var raw = context.Request.Body.As<string>();
      if (String.IsNullOrEmpty(raw) || raw.Length > 6144) { return String.Empty; }
      try {
        var request = JObject.Parse(raw);
        var messages = request["messages"] as JArray;
        if (messages == null || messages.Count == 0 || messages.Count > 4) { return String.Empty; }
        if (request["stream"]?.ToString().ToLowerInvariant() == "true") { return String.Empty; }
        if (request["tools"] != null || request["functions"] != null) { return String.Empty; }
        var safe = new JArray();
        int length = 0;
        foreach (var item in messages) {
          var msg = item as JObject;
          if (msg == null || msg["role"]?.Type != JTokenType.String ||
              msg["content"]?.Type != JTokenType.String) { return String.Empty; }
          var role = (string)msg["role"];
          var text = (string)msg["content"];
          if (role != "user" && role != "assistant" && role != "system" && role != "developer") { return String.Empty; }
          if (String.IsNullOrWhiteSpace(text)) { return String.Empty; }
          length += text.Length;
          if (length > 700) { return String.Empty; }
          safe.Add(new JObject(new JProperty("role", role), new JProperty("content", text)));
        }
        return new JObject(new JProperty("model", "__DEPLOYMENT__"),
          new JProperty("messages", safe), new JProperty("max_completion_tokens", 256),
          new JProperty("reasoning_effort", "none"), new JProperty("store", false)).ToString(Newtonsoft.Json.Formatting.None);
      } catch (Newtonsoft.Json.JsonException) {
        return String.Empty;
      }
    }

@{
      if (context.Response.StatusCode != 200) { return "{}"; }
      try {
        var body = context.Response.Body.As<JObject>(preserveContent: true);
        var u = body["usage"] as JObject;
        if (u == null) { return "{}"; }
        var clean = new JObject();
        foreach (var key in new [] { "prompt_tokens", "completion_tokens", "total_tokens" }) {
          var count = u[key];
          if (count?.Type == JTokenType.Integer) { clean[key] = (long)count; }
        }
        return clean.ToString(Newtonsoft.Json.Formatting.None);
      } catch (Newtonsoft.Json.JsonException) {
        return "{}";
      }
    }

metadata.value:
@{
        Guid parsed;
        return Guid.TryParse(context.Response.Headers.GetValueOrDefault("apim-request-id", ""), out parsed) ? parsed.ToString() : "unavailable";
      }
